/**
 * Calendar arithmetic for subscription periods, and the charges they carry.
 *
 * Everything is UTC. A period's end keeps its start's time of day; when the
 * target month has no such day the end is clamped to that month's last day.
 * Each period is measured from its own start, so a clamp carries forward
 * (28 February → 28 March).
 *
 * Must call (do not reimplement): getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { BillingInterval, PlanId } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Months a period of this interval covers. */
export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/** The end of a period that starts at `start` and runs for one `interval`. */
export function periodEndFor(start: Date, interval: BillingInterval): Date {
  const monthIndex = start.getUTCMonth() + monthsIn(interval);
  const year = start.getUTCFullYear() + Math.floor(monthIndex / 12);
  const month = monthIndex % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();

  return new Date(
    Date.UTC(
      year,
      month,
      Math.min(start.getUTCDate(), lastDay),
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/** The full charge for one period, in cents: price per seat × seats × months. */
export function periodCharge(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly * seats * monthsIn(interval)
  );
}

/**
 * The share of a full-period amount owed for a change made at `at`: scaled by
 * the whole-or-started days left over the days in the period, rounded down to
 * whole cents. Nothing is owed once the period end has been reached.
 */
export function prorateCents(
  fullCents: number,
  at: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  const msLeft = periodEnd.getTime() - at.getTime();
  if (msLeft <= 0) return 0;

  const daysLeft = Math.ceil(msLeft / MS_PER_DAY);
  const daysInPeriod = Math.max(
    1,
    Math.round((periodEnd.getTime() - periodStart.getTime()) / MS_PER_DAY),
  );

  return Math.floor((fullCents * daysLeft) / daysInPeriod);
}

