/**
 * Writes a subscription change together with the invoices it raises, in one
 * transaction: a period is never advanced without being billed, and a billed
 * period is never billed twice.
 */
export async function commitSubscriptionChange(
  orgId: OrgId,
  patch: SubscriptionPatch,
  drafts: readonly InvoiceDraft[],
): Promise<{ subscription: Subscription; invoices: readonly Invoice[] }> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const issued: Invoice[] = [];

    for (const draft of drafts) {
      const counted = tx
        .select({ total: sql<number>`count(*)` })
        .from(invoices)
        .where(orgPredicate(invoices.orgId, orgId))
        .get();
      const sequence = (counted?.total ?? 0) + 1;

      const row = tx
        .insert(invoices)
        .values({
          id: newId(),
          orgId,
          number: invoiceNumber(draft.periodStart, sequence),
          amountCents: draft.amountCents,
          currency: "usd",
          periodStart: draft.periodStart,
          periodEnd: draft.periodEnd,
          paidAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      issued.push(toInvoice(row));
    }

    const row = tx
      .update(subscriptions)
      .set({ ...patch, updatedAt: stamp })
      .where(orgPredicate(subscriptions.orgId, orgId))
      .returning()
      .get();

    if (!row) throw new Error(`Subscription for org ${orgId} not found`);
    return { subscription: toSubscription(row), invoices: issued };
  });
}

/** Subscriptions the renewal job may settle: active or canceled, in workspaces not archived. Cross-tenant by design, it sweeps every org. */
export async function listRenewableSubscriptions(): Promise<
  readonly Subscription[]
> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        inArray(subscriptions.status, ["active", "canceled"]),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map(({ subscription }) => toSubscription(subscription));
}

/** `INV-<year the period starts>-<sequence>`, the sequence padded to four digits. */
function invoiceNumber(periodStart: IsoTimestamp, sequence: number): string {
  return `INV-${periodStart.slice(0, 4)}-${String(sequence).padStart(4, "0")}`;
}
