export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const now = new Date();
  const { patch, drafts } = planChangeTerms(current, input, now);
  const subscription = await recordChange(input.orgId, patch, drafts, now);

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: current.plan,
    to: input.plan,
  });

  return subscription;
}

export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const current = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const plan = current.plan;

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  // Only seats added to a paid, active subscription are billed; removing seats
  // credits nothing, and the free plan and trials never charge for seats.
  const added = input.seats - current.seats;
  const now = new Date();
  const billable = current.status === "active" && plan !== "free" && added > 0;
  const drafts = billable
    ? proratedDrafts(current, periodCharge(plan, added, current.interval), now)
    : [];

  return recordChange(input.orgId, { seats: input.seats }, drafts, now);
}

/**
 * Publishes `billing.invoice_issued` once per invoice. Invoices carry no actor,
 * the same as a renewal, so the owner is told about them whoever made the change.
 */
export async function announceInvoices(
  orgId: OrgId,
  issued: readonly Invoice[],
  at: Date,
): Promise<void> {
  for (const invoice of issued) {
    await emit("billing.invoice_issued", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(at),
      invoiceId: invoice.id,
      invoiceNumber: invoice.number,
      amountCents: invoice.amountCents,
      periodStart: invoice.periodStart,
      periodEnd: invoice.periodEnd,
    });
  }
}

/** Records a change and the invoices it raises, then announces those invoices. */
async function recordChange(
  orgId: OrgId,
  patch: SubscriptionPatch,
  drafts: readonly InvoiceDraft[],
  at: Date,
): Promise<Subscription> {
  const recorded = await subscriptionRepo.commitSubscriptionChange(
    orgId,
    patch,
    drafts,
  );
  await announceInvoices(orgId, recorded.invoices, at);
  return recorded.subscription;
}

/**
 * The record and charge for moving to `input.plan`:
 *  - to the free plan: nothing;
 *  - off the free plan: a fresh period from `at` with the chosen interval, invoiced in full;
 *  - during a trial: nothing, and the trial period is kept (the first invoice comes when it ends);
 *  - while active, between paid plans: the price increase, prorated; a downgrade or the same plan charges nothing.
 */
function planChangeTerms(
  current: Subscription,
  input: ChangePlanInput,
  at: Date,
): { patch: SubscriptionPatch; drafts: readonly InvoiceDraft[] } {
  const patch: SubscriptionPatch = {
    plan: input.plan,
    interval: input.interval,
    status: "active",
  };

  if (input.plan === "free") return { patch, drafts: [] };

  if (current.plan === "free") {
    const periodStart = toIsoTimestamp(at);
