/**
 * Renews subscriptions whose period has ended, invoicing each paid period, and
 * moves cancelled subscriptions to the free plan on their cancellation date.
 *
 * Must call (do not reimplement): periodEndFor, periodCharge, commitSubscriptionChange, announceInvoices, emit
 */
import { periodCharge, periodEndFor } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import type {
  InvoiceDraft,
  SubscriptionPatch,
} from "@/server/repositories/subscription-repository";
import { announceInvoices } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { JobResult } from "@/server/jobs/types";

/** Where a cancelled subscription lands, and the period it restarts on. */
const FALLBACK_PLAN = "free" as const;
const FALLBACK_INTERVAL = "monthly" as const;

const logger = createLogger("billing-renewal-job");

type Period = { readonly start: Date; readonly end: Date };

/**
 * Settles every live subscription against `now`. A subscription that changes
 * is counted as processed; a failure is logged and leaves that subscription
 * for the next run. Replay-safe: once settled, a second run at the same
 * instant finds nothing due and bills nothing.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listRenewableSubscriptions();

    for (const subscription of subscriptions) {
      try {
        if (await settleSubscription(subscription, now)) {
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Returns whether the subscription was due and has been settled. */
async function settleSubscription(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.status !== "canceled") {
    if (new Date(subscription.currentPeriodEnd).getTime() > now.getTime()) {
      return false;
    }
    await advancePeriods(subscription, now);
    return true;
  }

  const cancelledAt = subscription.cancelAt;
  if (cancelledAt === null || new Date(cancelledAt).getTime() > now.getTime()) {
    return false;
  }
  await endCancellation(subscription, cancelledAt, now);
  return true;
}

/**
 * Ends a cancellation as of its date: the workspace moves to the free plan
 * with a fresh monthly period starting then, and `billing.plan_changed` is
 * published once. Nothing is invoiced.
 */
async function endCancellation(
  subscription: Subscription,
  cancelledAt: IsoTimestamp,
  now: Date,
): Promise<void> {
  await advancePeriods(
    {
      ...subscription,
      plan: FALLBACK_PLAN,
      interval: FALLBACK_INTERVAL,
      status: "active",
      cancelAt: null,
      currentPeriodStart: cancelledAt,
      currentPeriodEnd: toIsoTimestamp(
        periodEndFor(new Date(cancelledAt), FALLBACK_INTERVAL),
      ),
    },
    now,
  );

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: cancelledAt,
    from: subscription.plan,
    to: FALLBACK_PLAN,
  });
}

/**
 * Opens every period the subscription has run through by `now` and records
 * them in one commit: each paid period is invoiced in full at the seat count
 * now on the subscription, and the subscription ends on the last period.
 */
async function advancePeriods(
  subscription: Subscription,
  now: Date,
): Promise<void> {
  const periods = periodsThrough(subscription, now);
  const last = periods.at(-1) ?? {
    start: new Date(subscription.currentPeriodStart),
    end: new Date(subscription.currentPeriodEnd),
  };

  const amountCents = periodCharge(
    subscription.plan,
    subscription.seats,
    subscription.interval,
  );
  const drafts: readonly InvoiceDraft[] =
    amountCents > 0
      ? periods.map((period) => ({
          periodStart: toIsoTimestamp(period.start),
          periodEnd: toIsoTimestamp(period.end),
          amountCents,
        }))
      : [];

  const patch: SubscriptionPatch = {
    plan: subscription.plan,
    interval: subscription.interval,
    status: subscription.status,
    cancelAt: subscription.cancelAt,
    currentPeriodStart: toIsoTimestamp(last.start),
    currentPeriodEnd: toIsoTimestamp(last.end),
  };

  const { invoices } = await subscriptionRepo.commitSubscriptionChange(
    subscription.orgId,
    patch,
    drafts,
  );
  await announceInvoices(subscription.orgId, invoices, now);
}

/**
 * Each period to open after the current one, in order, until the last one
 * ends after `now`. Each starts where the previous ended.
 */
function periodsThrough(subscription: Subscription, now: Date): readonly Period[] {
  const periods: Period[] = [];
  let start = new Date(subscription.currentPeriodEnd);

  while (start.getTime() <= now.getTime()) {
    const end = periodEndFor(start, subscription.interval);
    periods.push({ start, end });
    start = end;
  }

  return periods;
}

