/**
 * Period arithmetic and proration: clamped month ends, carried-forward clamps,
 * whole-or-started days left, and rounding down to whole cents.
 */
import { describe, expect, it } from "vitest";
import {
  periodCharge,
  periodEndFor,
  prorateCents,
} from "@/lib/billing-period";

const at = (iso: string) => new Date(iso);

describe("lib/billing-period", () => {
  it("ends a monthly period on the same day of the next month", () => {
    expect(periodEndFor(at("2026-03-10T09:30:00.000Z"), "monthly").toISOString()).toBe(
      "2026-04-10T09:30:00.000Z",
    );
  });

  it("clamps a month end to the last day of a shorter month", () => {
    expect(periodEndFor(at("2027-01-31T00:00:00.000Z"), "monthly").toISOString()).toBe(
      "2027-02-28T00:00:00.000Z",
    );
  });

  it("carries a clamped day forward from the period start", () => {
    expect(periodEndFor(at("2027-02-28T00:00:00.000Z"), "monthly").toISOString()).toBe(
      "2027-03-28T00:00:00.000Z",
    );
  });

  it("rolls an annual period to the same day and month of the next year", () => {
    expect(periodEndFor(at("2027-06-15T12:00:00.000Z"), "annual").toISOString()).toBe(
      "2028-06-15T12:00:00.000Z",
    );
  });

  it("clamps a leap day on an annual period to the 28th", () => {
    expect(periodEndFor(at("2028-02-29T00:00:00.000Z"), "annual").toISOString()).toBe(
      "2029-02-28T00:00:00.000Z",
    );
  });

  it("charges the monthly price per seat times seats times months", () => {
    expect(periodCharge("growth", 4, "monthly")).toBe(1_900 * 4);
    expect(periodCharge("starter", 3, "annual")).toBe(900 * 3 * 12);
    expect(periodCharge("free", 3, "monthly")).toBe(0);
  });

  it("counts a partly elapsed day as a day left", () => {
    // 14 days and 22 hours left in a 30-day period: 15 days owed.
    const start = at("2026-05-01T00:00:00.000Z");
    const end = at("2026-05-31T00:00:00.000Z");
    const changed = at("2026-05-16T02:00:00.000Z");

    expect(prorateCents(3_000, changed, start, end)).toBe(
      Math.floor((3_000 * 15) / 30),
    );
  });

  it("owes nothing once the period end has been reached", () => {
    const start = at("2026-05-01T00:00:00.000Z");
    const end = at("2026-06-01T00:00:00.000Z");

    expect(prorateCents(3_800, end, start, end)).toBe(0);
    expect(prorateCents(3_800, at("2026-06-02T00:00:00.000Z"), start, end)).toBe(0);
  });

  it("rounds the prorated amount down to whole cents", () => {
    // 1_900 × 8 / 31 = 490.32…, which is 490 cents.
    expect(
      prorateCents(
        1_900,
        at("2026-01-24T00:00:00.000Z"),
        at("2026-01-01T00:00:00.000Z"),
        at("2026-02-01T00:00:00.000Z"),
      ),
    ).toBe(490);
  });
});

