/**
 * Billing renewal: periods roll on at their end, every paid period is invoiced,
 * cancellations end on their date, archived workspaces are skipped, and a
 * second run at the same instant changes nothing.
 */
import { and, eq } from "drizzle-orm";
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import {
  getDb,
  notifications,
  organizations,
  subscriptions,
} from "@/server/db";
import type { NewSubscriptionRow } from "@/server/db/schema/billing";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as billingService from "@/server/services/billing-service";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends "billing.invoice_issued" | "billing.plan_changed">(
  type: K,
): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function setSubscription(tenant: Tenant, values: Partial<NewSubscriptionRow>): void {
  getDb()
    .update(subscriptions)
    .set(values)
    .where(eq(subscriptions.orgId, tenant.org.id))
    .run();
}

async function invoicesOf(tenant: Tenant) {
  return invoiceRepo.listInvoices(tenant.org.id);
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("runBillingRenewalJob", () => {
  it("opens one period per elapsed interval and invoices each paid period", async () => {
    const tenant = await createTenant("renew-catch-up", "growth");
    setSubscription(tenant, {
      status: "active",
      seats: 4,
      interval: "monthly",
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });
    const issued = capture("billing.invoice_issued");

    const result = await runBillingRenewalJob(new Date("2026-04-15T10:00:00.000Z"));

    expect(result.processed).toBe(1);
    expect(result.failed).toBe(0);

    const invoices = await invoicesOf(tenant);
    expect(invoices.map((invoice) => [invoice.periodStart, invoice.periodEnd])).toEqual([
      ["2026-03-01T00:00:00.000Z", "2026-04-01T00:00:00.000Z"],
      ["2026-02-01T00:00:00.000Z", "2026-03-01T00:00:00.000Z"],
      ["2026-04-01T00:00:00.000Z", "2026-05-01T00:00:00.000Z"],
    ]);
    expect(invoices.every((invoice) => invoice.amountCents === 1_900 * 4)).toBe(true);
    expect(invoices.every((invoice) => invoice.currency === "usd")).toBe(true);
    expect(invoices.every((invoice) => invoice.paidAt === null)).toBe(true);
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(3);

    const subscription = await billingService.getBillingSummary(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(subscription.subscription.currentPeriodStart).toBe("2026-04-01T00:00:00.000Z");
    expect(subscription.subscription.currentPeriodEnd).toBe("2026-05-01T00:00:00.000Z");

    expect(issued).toHaveLength(3);
    expect(issued.every((event) => event.actorId === null)).toBe(true);
  });

  it("is replay-safe: a second run at the same instant bills nothing", async () => {
    const tenant = await createTenant("renew-replay", "starter");
    setSubscription(tenant, {
      status: "active",
      seats: 2,
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });
    const now = new Date("2026-02-10T00:00:00.000Z");

    await runBillingRenewalJob(now);
    const before = (await invoicesOf(tenant)).length;
    const issued = capture("billing.invoice_issued");

    const again = await runBillingRenewalJob(now);

    expect(again.processed).toBe(0);
    expect((await invoicesOf(tenant)).length).toBe(before);
    expect(issued).toHaveLength(0);
  });

  it("leaves a subscription alone while its period is still running", async () => {
    const tenant = await createTenant("renew-running", "growth");
    setSubscription(tenant, {
      status: "active",
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });

    const result = await runBillingRenewalJob(new Date("2026-01-20T00:00:00.000Z"));

    expect(result.processed).toBe(0);
    expect(await invoicesOf(tenant)).toHaveLength(0);
  });

  it("opens free-plan periods without invoicing them", async () => {
    const tenant = await createTenant("renew-free", "free");
    setSubscription(tenant, {
      plan: "free",
      status: "active",
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-05T00:00:00.000Z"));

    expect(await invoicesOf(tenant)).toHaveLength(0);
    const summary = await billingService.getBillingSummary(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(summary.subscription.currentPeriodEnd).toBe("2026-04-01T00:00:00.000Z");
  });

  it("ends a cancellation on its date, moving to the free plan without an invoice", async () => {
    const tenant = await createTenant("renew-cancel", "growth");
    setSubscription(tenant, {
      status: "canceled",
      cancelAt: "2026-03-01T00:00:00.000Z",
      currentPeriodStart: "2026-02-01T00:00:00.000Z",
      currentPeriodEnd: "2026-03-01T00:00:00.000Z",
    });
    const changed = capture("billing.plan_changed");

    await runBillingRenewalJob(new Date("2026-02-28T23:00:00.000Z"));
    expect(changed).toHaveLength(0);

    await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));

    expect(changed).toHaveLength(1);
    expect(changed[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: null,
      from: "growth",
      to: "free",
    });
    expect(await invoicesOf(tenant)).toHaveLength(0);

    const summary = await billingService.getBillingSummary(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(summary.subscription).toMatchObject({
      plan: "free",
      status: "active",
      interval: "monthly",
      cancelAt: null,
      currentPeriodStart: "2026-03-01T00:00:00.000Z",
      currentPeriodEnd: "2026-04-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));
    expect(changed).toHaveLength(1);
  });

  it("settles trials and past-due subscriptions no differently from before", async () => {
    const trialing = await createTenant("renew-trialing", "growth");
    setSubscription(trialing, {
      status: "trialing",
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-01-15T00:00:00.000Z",
    });
    const pastDue = await createTenant("renew-past-due", "growth");
    setSubscription(pastDue, {
      status: "past_due",
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-01-15T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-06-01T00:00:00.000Z"));

    expect(await invoicesOf(trialing)).toHaveLength(0);
    expect(await invoicesOf(pastDue)).toHaveLength(0);
  });

  it("skips archived workspaces entirely", async () => {
    const tenant = await createTenant("renew-archived", "growth");
    setSubscription(tenant, {
      status: "active",
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });
    getDb()
      .update(organizations)
      .set({ archivedAt: "2026-01-15T00:00:00.000Z" })
      .where(eq(organizations.id, tenant.org.id))
      .run();

    await runBillingRenewalJob(new Date("2026-06-01T00:00:00.000Z"));

    expect(await invoicesOf(tenant)).toHaveLength(0);
  });

  it("tells only the workspace owner, once per invoice, and audits each one", async () => {
    const tenant = await createTenant("renew-notify", "growth");
    setSubscription(tenant, {
      status: "active",
      seats: 1,
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-02-10T00:00:00.000Z"));

    const rows = getDb()
      .select()
      .from(notifications)
      .where(
        and(
          eq(notifications.orgId, tenant.org.id),
          eq(notifications.kind, "invoice_issued"),
        ),
      )
      .all();
    expect(rows).toHaveLength(1);
    expect(rows[0]?.recipientId).toBe(tenant.userIds.owner);

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 100,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "billing.invoice_issued",
      subjectKind: "subscription",
      subjectId: tenant.org.id,
    });
  });
});

describe("mid-period charges", () => {
  it("charges the prorated price of seats added to an active paid subscription", async () => {
    const tenant = await createTenant("prorate-seats", "growth");
    setSubscription(tenant, {
